using System;using System.Data;using System.Diagnostics;using System.Drawing;using System.IO;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmDataManagement:StyledForm {
 ComboBox table=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=190};TextBox search=new TextBox{Width=250};DataGridView g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoGenerateColumns=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells,SelectionMode=DataGridViewSelectionMode.FullRowSelect};DataTable data;string pathColumn;
 public FrmDataManagement():this("Students"){}public FrmDataManagement(string initialTable){Text="Data Management";Size=new Size(1200,680);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=58,Padding=new Padding(9)};table.Items.AddRange(new object[]{"Students","Parents","Guardians","Applications","Documents","Payments","Admission List","Semester Results","Refunds"});bar.Controls.Add(new Label{Text="Table",AutoSize=true,Margin=new Padding(3,9,3,3)});bar.Controls.Add(table);bar.Controls.Add(new Label{Text="Search",AutoSize=true,Margin=new Padding(20,9,3,3)});bar.Controls.Add(search);Controls.Add(g);Controls.Add(bar);Controls.Add(UiTheme.Heading("Database Records","View registration information stored in the Access database"));table.SelectedIndexChanged+=delegate{LoadData();};search.TextChanged+=delegate{Filter();};g.CellContentClick+=GridClick;int selected=table.Items.IndexOf(initialTable);table.SelectedIndex=selected<0?0:selected;}
 void LoadData(){try{g.Columns.Clear();pathColumn=null;data=new DataManagementQuery().Load(Convert.ToString(table.SelectedItem));g.DataSource=data;ConfigurePreview();Filter();}catch(Exception ex){MessageBox.Show("Data could not be loaded.\r\n"+ex.Message);}}
 void ConfigurePreview(){string selected=Convert.ToString(table.SelectedItem);if(selected=="Documents")pathColumn="FilePath";else if(selected=="Students")pathColumn="ProfilePhotoPath";else if(selected=="Payments")pathColumn="ReceiptFilePath";if(pathColumn==null||!g.Columns.Contains(pathColumn))return;var preview=new DataGridViewImageColumn{Name="ImagePreview",HeaderText="Photo Preview",Width=105,ImageLayout=DataGridViewImageCellLayout.Zoom};preview.DefaultCellStyle.NullValue=null;g.Columns.Insert(0,preview);var view=new DataGridViewButtonColumn{Name="ViewFile",HeaderText="View",Text="View",UseColumnTextForButtonValue=true,Width=75};g.Columns.Insert(1,view);g.Columns[pathColumn].Visible=false;if(selected=="Documents"&&g.Columns.Contains("FileName"))g.Columns["FileName"].Visible=false;foreach(DataGridViewRow row in g.Rows){string path=Convert.ToString(row.Cells[pathColumn].Value);row.Height=72;row.Cells["ImagePreview"].Value=Thumbnail(path);}}
 Image Thumbnail(string path){if(!IsImage(path))return null;try{using(var image=Image.FromFile(path))return new Bitmap(image,new Size(88,64));}catch{return null;}}bool IsImage(string path){if(!File.Exists(path))return false;string ext=Path.GetExtension(path).ToLowerInvariant();return ext==".jpg"||ext==".jpeg"||ext==".png";}
 void GridClick(object sender,DataGridViewCellEventArgs e){if(e.RowIndex<0||pathColumn==null||g.Columns[e.ColumnIndex].Name!="ViewFile")return;string path=Convert.ToString(g.Rows[e.RowIndex].Cells[pathColumn].Value);if(!File.Exists(path)){MessageBox.Show("The uploaded file could not be found.");return;}if(IsImage(path))ShowImage(path);else try{Process.Start(path);}catch(Exception ex){MessageBox.Show("The file could not be opened.\r\n"+ex.Message);}}
 void ShowImage(string path){using(var form=new Form{Text="Uploaded Photo",StartPosition=FormStartPosition.CenterParent,Size=new Size(850,680),BackColor=Color.Black})using(var picture=new PictureBox{Dock=DockStyle.Fill,SizeMode=PictureBoxSizeMode.Zoom}){using(var image=Image.FromFile(path))picture.Image=new Bitmap(image);form.Controls.Add(picture);form.ShowDialog(this);}}
 void Filter(){if(data==null)return;string text=search.Text.Replace("'","''");if(text==""){data.DefaultView.RowFilter="";return;}var parts=new System.Collections.Generic.List<string>();foreach(DataColumn c in data.Columns)if(c.DataType==typeof(string))parts.Add("Convert(["+c.ColumnName+"], 'System.String') LIKE '%"+text+"%'");data.DefaultView.RowFilter=string.Join(" OR ",parts.ToArray());}
} }
